import {SoundPlayer} from './sound-player.js';
import {api} from './remote.js';
import {sample,validation,duration,start,settle,left,totalLeft,pause,resume,skip,validSaved} from './engine.js';
const $=s=>document.querySelector(s),KEY='stage-timer-v1',colors=['#385e4b','#486579','#766044','#655a7a'];
let floatLaunching=false,remote=false,remoteRevision=-1,remoteInfo=null,remoteBusy=false,remoteQueue=Promise.resolve(),remoteClaim=0,remoteDraftPending=0;
let state={version:1,draft:sample(),run:null},owner=false,broken=false,audio,saveFailure=false;
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(!validSaved(saved))throw Error('invalid');state=saved;}}catch{broken=true;$('#storage-error').hidden=false;$('#storage-error').textContent='本地数据无法读取，已保留原始数据。请先检查浏览器存储设置；如要重新开始，可点击：';const b=document.createElement('button');b.textContent='重置本工具数据';b.onclick=()=>{if(confirm('确认清除本工具的计划和计时记录？')){localStorage.removeItem(KEY);location.reload();}};$('#storage-error').append(b);}
function save(){if(!owner||broken)return false;if(remote){if(!state.run)queueDraft();return true;}try{localStorage.setItem(KEY,JSON.stringify(state));saveFailure=false;return true;}catch{saveFailure=true;$('#storage-error').hidden=false;$('#storage-error').textContent='自动保存失败（可能是存储空间或浏览器权限限制）。当前页面仍可计时，但刷新后可能丢失进度。';return false;}}
const el=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
function renderEditor(){
 $('#task-name').value=state.draft.name;$('#task-total').value=state.draft.total;const box=$('#stage-editor');box.replaceChildren();
 state.draft.stages.forEach((s,i)=>{const row=el('div','','stage-row');row.append(el('span',String(i+1).padStart(2,'0'),'stage-number'));const name=document.createElement('input');name.value=s.name;name.maxLength=100;name.setAttribute('aria-label',`阶段 ${i+1} 名称`);name.oninput=()=>{state.draft.stages[i].name=name.value;save();renderSummary();};const minutes=document.createElement('input');minutes.type='number';minutes.min=1/60;minutes.step='any';minutes.value=s.minutes;minutes.setAttribute('aria-label',`阶段 ${i+1} 时长（分钟）`);minutes.oninput=()=>{state.draft.stages[i].minutes=Number(minutes.value);save();renderSummary();};row.append(name,minutes);const actions=el('div','','row-actions');[['↑','上移',-1],['↓','下移',1],['×','删除',0]].forEach(([symbol,title,dir])=>{const b=el('button',symbol);b.setAttribute('aria-label',`${title}阶段 ${i+1}`);b.title=title;b.disabled=!owner||(dir===-1&&i===0)||(dir===1&&i===state.draft.stages.length-1);b.onclick=()=>{if(!owner)return;if(dir)[state.draft.stages[i],state.draft.stages[i+dir]]=[state.draft.stages[i+dir],state.draft.stages[i]];else state.draft.stages.splice(i,1);save();renderEditor();};actions.append(b);});row.append(actions);box.append(row);});
 $('#editor').querySelectorAll('input').forEach(e=>e.disabled=!owner||broken);$('#add').disabled=!owner||broken;renderSummary();
}
function renderSummary(){const p=state.draft,sum=p.stages.reduce((n,s)=>n+(s.minutes||0),0),error=validation(p);$('#sum-value').textContent=Number(sum.toFixed(2));$('#stage-count').textContent=`${p.stages.length} 个阶段 · 预计 ${duration((p.total||0)*60000)}`;$('#validation').textContent=error||'时间刚刚好，可以开始专注。';$('#validation').classList.toggle('invalid',!!error);$('#start').disabled=!!error||!owner||broken;$('#mini-track').replaceChildren();p.stages.forEach((s,i)=>{const part=el('span','');part.style.flex=Math.max(0,s.minutes)||0;part.style.background=colors[i%4];$('#mini-track').append(part);});}
function fmt(ms){const sec=Math.ceil(ms/1000),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function renderRun(){const r=state.run;if(!r)return;const active=['running','paused'].includes(r.status),now=Date.now(),idx=r.index;document.documentElement.style.setProperty('--stage',colors[idx%4]);$('#focus-name').textContent=r.plan.name;$('#run-state').textContent=({running:'正在专注',paused:'已暂停',finished:'等待收尾检查',ended:'计时已结束'})[r.status];$('#current-stage').textContent=active?`${idx+1}/${r.plan.stages.length} · ${r.plan.stages[idx].name}`:r.status==='finished'?'计划阶段已结束':'本次计时已停止';$('#clock').textContent=fmt(left(r,now));$('#clock-caption').textContent=r.status==='paused'?'阶段与整体计时已暂停':active?'当前阶段剩余':r.status==='finished'?'请收尾并检查成果，成果是否完成由你判断':'计划已保留，可返回修改';const next=r.plan.stages[idx+1];$('#next-stage').textContent=active?(next?`${next.name} · ${duration(next.minutes*60000)}`:'收尾并检查成果'):'返回计划可开始新一轮';$('#pause').textContent=r.status==='paused'?'继续':'暂停';$('#skip').textContent=idx===r.plan.stages.length-1?'提前结束最后阶段':'提前进入下一阶段';['pause','skip','end'].forEach(id=>{$('#'+id).hidden=!active;$('#'+id).disabled=!owner||broken;});$('#edit-again').hidden=active;$('#edit-again').disabled=!owner||broken;
 const remain=totalLeft(r,now),total=r.plan.total*60000,percent=r.status==='ended'?(r.stoppedProgress||0):Math.max(0,Math.min(100,(1-remain/total)*100));$('#progress').value=percent;$('#progress-label').textContent=`任务进度 ${Math.floor(percent)}%`;$('#total-left').textContent=r.status==='ended'?'已停止':`总剩余 ${fmt(remain)}`;$('#journey-count').textContent=`${r.plan.stages.length} STAGES`;$('#stage-list').replaceChildren();r.plan.stages.forEach((s,i)=>{const done=!!r.outcomes[i],current=active&&i===idx;const li=el('li','',current?'active':done?'done':'');li.append(el('span',done?'✓':String(i+1),'step-dot'));const body=el('div','');body.append(el('strong',s.name),el('small',`${duration(s.minutes*60000)} · ${done?(r.outcomes[i]==='early'?'已完成（提前结束）':'已完成'):current?(r.status==='paused'?'进行中 · 暂停':'进行中'):r.status==='ended'&&i===idx?'已中止':'未开始'}`));li.append(body);$('#stage-list').append(li);});$('#notice').hidden=!r.notice;if($('#notice').textContent!==(r.notice||''))$('#notice').textContent=r.notice||'';document.title=active?`${fmt(left(r,now))} · ${r.plan.stages[idx].name} · 留刻`:'留刻 · 分阶段任务计时器';}
function render(){const running=!!state.run;$('#editor').hidden=running;$('#focus').hidden=!running;$('#tab-warning').hidden=owner||broken;if(running)renderRun();else renderEditor();}
const soundPlayer=new SoundPlayer();let soundSetting={selected:'builtin',url:null},soundReady=false;
function setSound(value){soundSetting=value;const select=$('#sound-choice');select.replaceChildren();for(const item of value.options){const option=el('option',item.name);option.value=item.id;select.append(option);}select.value=value.selected;$('#remove-sound').hidden=!value.options.some(x=>x.id.startsWith('custom-'));}
async function sound(){try{await soundPlayer.play(soundSetting);soundReady=true;$('#sound-status').textContent='已播放 · 请确认实际听到声音';return true;}catch(e){$('#sound-status').textContent='播放失败：'+e.message;return false;}}
async function loadSounds(){try{setSound(await api('sounds'));}catch{$('#sound-status').textContent='声音设置无法读取，请确认本地服务运行';}}
$('#sound-choice').onchange=async e=>{try{setSound(await api('sounds',{type:'select',id:e.target.value}));$('#sound-status').textContent='提示音已保存，可点击测试';}catch(e){$('#sound-status').textContent=e.message;await loadSounds();}};
$('#remove-sound').onclick=async()=>{try{setSound(await api('sounds',{type:'remove'}));$('#sound-status').textContent='已移除上传音频';}catch(e){$('#sound-status').textContent=e.message;}};
$('#upload-sound').onclick=()=>$('#sound-file').click();
$('#sound-file').onchange=async e=>{
 const file=e.target.files[0];if(!file)return;
 $('#upload-sound').disabled=true;
 try{
  if(file.size>5*1024*1024)throw Error('请选择不超过 5 MB 的音频');
  const bytes=await file.arrayBuffer(),context=new AudioContext();
  try{const decoded=await context.decodeAudioData(bytes.slice(0));if(decoded.duration>30||decoded.duration<=0)throw Error('提示音需在 30 秒以内');}finally{await context.close();}
  const ext=file.name.split('.').pop().toLowerCase(),mime=({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg',webm:'audio/webm'})[ext]||file.type;
  const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
  setSound(await api('sounds',{type:'upload',name:file.name,mime,base64}));$('#sound-status').textContent='上传并保存成功 · 点击测试试听（仅存本机）';
 }catch(error){$('#sound-status').textContent='未上传：'+(error.message||'无法解码此音频，请使用 MP3 或 WAV');}
 finally{e.target.value='';$('#upload-sound').disabled=false;}
};
await loadSounds();

function announce(message){if(soundReady)void sound();else $('#sound-status').textContent='需要点击“测试提示音”启用声音';if('Notification'in window&&Notification.permission==='granted'){try{new Notification('留刻 · 阶段提醒',{body:message,tag:'stage-timer-transition'});}catch{$('#sound-status').textContent='系统通知未能发出，请检查浏览器设置';}}}
function tick(){if(!state.run)return;if(owner&&!broken&&!remote&&!floatLaunching){const events=settle(state.run,Date.now());if(events.length){save();announce(state.run.notice);}}renderRun();}
function updateRun(action,type){if(!owner||broken)return;if(remote){void remoteAction(type);return;}tick();action(state.run,Date.now());save();render();}
$('#task-name').oninput=e=>{state.draft.name=e.target.value;save();renderSummary();};$('#task-total').oninput=e=>{state.draft.total=Number(e.target.value);save();renderSummary();};$('#add').onclick=()=>{if(!owner||state.draft.stages.length>=100)return;state.draft.stages.push({name:'新阶段',minutes:15});save();renderEditor();};$('#start').onclick=()=>{if(!owner||validation(state.draft))return;$('#start-dialog').showModal();};$('#dialog-test').onclick=async()=>{$('#dialog-sound').textContent=await sound()?'已播放测试音。请确认耳机或扬声器确实有声音。':'无法播放，请检查浏览器声音权限与设备音量。';};$('#start-dialog').addEventListener('close',()=>{if($('#start-dialog').returnValue==='start'&&owner&&!validation(state.draft)){if(remote){void remoteAction('start');return;}state.run=start(state.draft,Date.now());save();render();}});$('#sound').onclick=sound;
$('#pause').onclick=()=>{updateRun((r,now)=>r.status==='paused'?resume(r,now):pause(r,now),state.run.status==='paused'?'resume':'pause');};$('#skip').onclick=()=>{updateRun(skip,'skip');};$('#end').onclick=()=>$('#end-dialog').showModal();$('#end-dialog').addEventListener('close',()=>{if($('#end-dialog').returnValue==='end')updateRun((r,now)=>{if(!['running','paused'].includes(r.status))return;r.stoppedProgress=(1-totalLeft(r,now)/(r.plan.total*60000))*100;r.status='ended';r.remaining=0;r.notice='你已结束本次计时。计划已保留，成果是否完成由你判断。';},'end');});$('#edit-again').onclick=()=>{if(!owner)return;if(remote){void remoteAction('edit');return;}state.run=null;save();document.title='留刻 · 分阶段任务计时器';render();};
function notificationLabel(){if(remote&&remoteInfo?.nativeActive){$('#notification').textContent=remoteInfo.notifications?'桌面通知已开启':'开启桌面通知';return;}$('#notification').textContent=!('Notification'in window)?'浏览器不支持系统通知':Notification.permission==='granted'?'发送测试通知':Notification.permission==='denied'?'通知已被浏览器阻止':'开启系统通知';}
$('#notification').onclick=async()=>{if(remote&&remoteInfo?.nativeActive){await remoteAction('notifications',!remoteInfo.notifications);return;}if(!('Notification'in window))return;try{let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission==='granted')new Notification('留刻 · 测试通知',{body:'如果看到这条通知，系统通知通道可用。后台到点仍受浏览器与系统限制。',tag:'stage-timer-test'});else $('#sound-status').textContent=permission==='denied'?'请在浏览器网站设置和系统通知设置中允许通知。':'未授权通知，仍可使用页面提醒。';}catch{$('#sound-status').textContent='系统通知不可用，请检查浏览器权限。';}notificationLabel();};
try{const initial=await api('state');if(initial.state)applyRemote(initial,true);}catch{}
window.addEventListener('storage',e=>{if(e.key===KEY&&!owner&&!remote){try{const s=JSON.parse(e.newValue);if(validSaved(s)){state=s;render();}}catch{}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();notificationLabel();}});window.addEventListener('pageshow',tick);setInterval(tick,200);notificationLabel();render();
if(navigator.locks){navigator.locks.request('stage-timer-owner',async()=>{if(!broken&&!remote){try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(validSaved(saved))state=saved;}}catch{}}owner=true;tick();render();await new Promise(()=>{});});}else{broken=true;$('#storage-error').hidden=false;$('#storage-error').textContent='此浏览器不支持安全的多标签页协调。请用新版 Chrome、Edge、Safari 或 Firefox，并通过 localhost 地址打开。';render();}

function desktopMessage(message){$('#desktop-status').hidden=false;$('#desktop-status').textContent=message;}
function applyRemote(value,force=false){
 if(value.sound&&value.sound.selected!==soundSetting.selected)setSound(value.sound);
 remoteInfo=value;if(!value.state)return;remote=true;if(value.revision<remoteRevision)return;
 if(value.revision!==remoteRevision||force){remoteRevision=value.revision;if(!remoteDraftPending){const wasRun=!!state.run;state=value.state;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}if(state.run||wasRun!==!!state.run||force)render();else if(document.activeElement?.tagName!=='INPUT')renderEditor();}}
 $('#float-toggle').textContent=value.nativeActive&&value.visible?'关闭悬浮计时':'开启悬浮计时';notificationLabel();
 desktopMessage(value.saveError||'桌面模式 · 计时由本地服务统一保存。主页面可最小化；请保持留刻应用或源码服务运行。');
}
function queueDraft(){const draft=structuredClone(state.draft);remoteDraftPending++;remoteQueue=remoteQueue.then(()=>api('action',{type:'draft',payload:draft})).then(value=>{remoteDraftPending--;applyRemote(value);}).catch(e=>{remoteDraftPending--;desktopMessage(e.message);});}
async function remoteAction(type,payload){await remoteQueue;try{const value=await api('action',{type,payload});applyRemote(value,true);}catch(e){desktopMessage(e.message);}}
$('#float-toggle').onclick=async()=>{if(!owner||broken)return;const button=$('#float-toggle');button.disabled=true;floatLaunching=true;try{await remoteQueue;const value=await api('float',{state,visible:!(remoteInfo?.nativeActive&&remoteInfo.visible)});applyRemote(value,true);}catch(e){desktopMessage(e.message+'；请确认已用新版启动脚本启动服务。');}finally{button.disabled=false;floatLaunching=false;}};
async function pollRemote(){if(remoteBusy)return;remoteBusy=true;try{const value=await api('state');if(value.state){applyRemote(value);if(owner&&!value.nativeActive&&value.event?.id>remoteClaim){remoteClaim=value.event.id;if((await api('claim',{id:remoteClaim})).claimed)announce(value.event.message);}}}catch{if(remote)desktopMessage('本地服务已断开。请重新运行启动脚本；页面仍显示按时间戳估算的剩余时间。');}finally{remoteBusy=false;}}
setInterval(pollRemote,250);
